'use strict';

const fs = require('fs');
const data = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < data.length && data[pos] <= 32) pos++;
  let value = 0;
  while (pos < data.length && data[pos] >= 48 && data[pos] <= 57) {
    value = value * 10 + data[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const sums = new Int32Array(M);

for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    sums[j] += nextInt();
  }
}

let answer = sums[0];
for (let j = 1; j < M; j++) {
  if (sums[j] < answer) answer = sums[j];
}

console.log(answer);
